package com.mediachafa.app;

import android.content.*;
import android.net.Uri;
import android.os.Build;
import androidx.activity.result.ActivityResult;
import com.getcapacitor.*;
import com.getcapacitor.annotation.*;
import org.apache.ftpserver.FtpServer;
import org.apache.commons.net.ftp.*;
import org.apache.commons.net.ftp.FTPSClient;
import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

@CapacitorPlugin(name="MediaFtp")
public class MediaFtpPlugin extends Plugin {
    private final ExecutorService io=Executors.newSingleThreadExecutor();
    private final Map<String,FileOutputStream> uploads=new ConcurrentHashMap<>();
    private FTPClient client;
    private String safePath(String raw) throws Exception { File root=FtpServerService.root(getContext()).getCanonicalFile(); if(!root.exists())root.mkdirs(); String p=raw==null?"":raw.replace('\\','/'); File f=new File(root,p).getCanonicalFile(); if(!f.equals(root)&&!f.getPath().startsWith(root.getPath()+File.separator))throw new SecurityException("Ruta fuera de MediaChafaFTP."); return f.getAbsolutePath(); }
    private String rel(File f) throws Exception {String root=FtpServerService.root(getContext()).getCanonicalPath();String p=f.getCanonicalPath();return p.equals(root)?"":p.substring(root.length()+1).replace(File.separatorChar,'/');}
    @PluginMethod public void getNetworkInfo(PluginCall c){String ip=localIp(); c.resolve(new JSObject().put("ip",ip));}
    @PluginMethod public void getServerStatus(PluginCall c){FtpServer s=FtpServerService.server;c.resolve(new JSObject().put("running",s!=null&&!s.isStopped()).put("port",FtpServerService.activePort).put("ip",FtpServerService.activeIp));}
    @PluginMethod public void startServer(PluginCall c){int port=c.getInt("port",2121);String ip=localIp();if(port<1024||port>65535||ip.isEmpty()){c.reject("Elegí un puerto válido y conectate a una red Wi-Fi.");return;}FtpServerService.activeIp=ip;Intent i=new Intent(getContext(),FtpServerService.class).putExtra("port",port).putExtra("writable",c.getBoolean("allowWrite",false)).putExtra("ip",ip);if(Build.VERSION.SDK_INT>=26)getContext().startForegroundService(i);else getContext().startService(i);io.execute(()->{try{for(int n=0;n<50;n++){FtpServer s=FtpServerService.server;if(s!=null&&!s.isStopped()){c.resolve(new JSObject().put("ip",ip).put("port",port));return;}Thread.sleep(100);}c.reject("El servidor no pudo iniciar; revisá el puerto y la red.");}catch(Exception e){c.reject(e.getMessage());}});}
    @PluginMethod public void stopServer(PluginCall c){getContext().stopService(new Intent(getContext(),FtpServerService.class));FtpServerService.server=null;c.resolve();}
    @PluginMethod public void listLocalFiles(PluginCall c){try{File d=new File(safePath(c.getString("path","")));if(!d.isDirectory())throw new IOException("La carpeta no existe.");JSArray a=new JSArray();File[] fs=d.listFiles();if(fs!=null){Arrays.sort(fs,Comparator.comparing(File::isFile).thenComparing(File::getName,String.CASE_INSENSITIVE_ORDER));for(File f:fs)a.put(new JSObject().put("name",f.getName()).put("relativePath",rel(f)).put("directory",f.isDirectory()).put("size",f.length()));}c.resolve(new JSObject().put("entries",a));}catch(Exception e){c.reject(e.getMessage());}}
    @PluginMethod public void createLocalFolder(PluginCall c){try{String name=validName(c.getString("name"));File d=new File(safePath(c.getString("parent","")),name);if(!d.mkdir())throw new IOException("No se pudo crear (quizá ya existe).");c.resolve();}catch(Exception e){c.reject(e.getMessage());}}
    @PluginMethod public void deleteLocalItem(PluginCall c){try{File f=new File(safePath(c.getString("path")));if(f.equals(FtpServerService.root(getContext()).getCanonicalFile()))throw new SecurityException("No se puede borrar la raíz.");deleteTree(f);c.resolve();}catch(Exception e){c.reject(e.getMessage());}}
    @PluginMethod public void moveLocalItem(PluginCall c){try{File src=new File(safePath(c.getString("path")));File destDir=new File(safePath(c.getString("destination","")));if(!destDir.isDirectory())throw new IOException("La carpeta destino no existe.");File dest=new File(destDir,src.getName());if(dest.exists())throw new IOException("Ya existe un elemento con ese nombre.");if(!src.renameTo(dest))throw new IOException("No se pudo mover el elemento.");c.resolve();}catch(Exception e){c.reject(e.getMessage());}}
    @PluginMethod public void beginLocalUpload(PluginCall c){try{String name=validName(c.getString("name"));File d=new File(safePath(c.getString("path","")));if(!d.isDirectory())throw new IOException("La carpeta destino no existe.");File target=new File(d,name);if(target.exists())throw new IOException("Ya existe un archivo con ese nombre.");String id=UUID.randomUUID().toString();File tmp=new File(d,"."+id+".upload");uploads.put(id,new FileOutputStream(tmp));tempFiles.put(id,tmp);targetFiles.put(id,target);c.resolve(new JSObject().put("uploadId",id));}catch(Exception e){c.reject(e.getMessage());}}
    private final Map<String,File> tempFiles=new ConcurrentHashMap<>(),targetFiles=new ConcurrentHashMap<>();
    @PluginMethod public void appendLocalUploadChunk(PluginCall c){String id=c.getString("uploadId"),b=c.getString("base64");try{FileOutputStream out=uploads.get(id);if(out==null)throw new IOException("Subida vencida.");byte[] data=android.util.Base64.decode(b,android.util.Base64.DEFAULT);if(data.length>300*1024)throw new IOException("Bloque demasiado grande.");out.write(data);c.resolve();}catch(Exception e){c.reject(e.getMessage());}}
    @PluginMethod public void finishLocalUpload(PluginCall c){String id=c.getString("uploadId");try{FileOutputStream out=uploads.remove(id);if(out==null)throw new IOException("Subida vencida.");out.close();File tmp=tempFiles.remove(id),target=targetFiles.remove(id);if(tmp==null||target==null)throw new IOException("No se encontró la subida temporal.");if(!tmp.renameTo(target))throw new IOException("No se pudo guardar el archivo.");c.resolve();}catch(Exception e){c.reject(e.getMessage());}}
    @PluginMethod public void cancelLocalUpload(PluginCall c){String id=c.getString("uploadId");try{FileOutputStream out=uploads.remove(id);if(out!=null)out.close();File f=tempFiles.remove(id);targetFiles.remove(id);if(f!=null)f.delete();c.resolve();}catch(Exception e){c.reject(e.getMessage());}}
    @PluginMethod public void connectPs4(PluginCall c){io.execute(()->{try{disconnect();String host=c.getString("host");int port=c.getInt("port",2121);if(host==null||!host.matches("[0-9]{1,3}(\\.[0-9]{1,3}){3}")||port<1||port>65535)throw new IOException("Ingresá una IP y puerto válidos.");boolean tls=c.getBoolean("ftps",false);client=tls?new FTPSClient(false):new FTPClient();client.setConnectTimeout(8000);client.setDefaultTimeout(8000);client.setDataTimeout(15000);client.connect(host,port);if(!FTPReply.isPositiveCompletion(client.getReplyCode()))throw new IOException("El servidor rechazó la conexión: "+client.getReplyString());client.setControlEncoding("UTF-8");client.enterLocalPassiveMode();client.setFileType(FTP.BINARY_FILE_TYPE);boolean anon=c.getBoolean("anonymous",true);if(!client.login(anon?"anonymous":c.getString("username",""),anon?"anonymous@mediachafa.local":c.getString("password","")))throw new IOException("El servidor rechazó el inicio de sesión.");if(client instanceof FTPSClient){FTPSClient f=(FTPSClient)client;f.execPBSZ(0);f.execPROT("P");}c.resolve(new JSObject().put("system",client.getSystemName()).put("path",client.printWorkingDirectory()).put("entries",entries(client.listFiles())));}catch(Exception e){disconnect();c.reject("Conexión FTP: "+e.getMessage());}});}
    @PluginMethod public void listPs4Files(PluginCall c){io.execute(()->{try{if(client==null||!client.isConnected())throw new IOException("No hay conexión FTP.");String path=c.getString("path","/");if(!client.changeWorkingDirectory(path))throw new IOException(client.getReplyString());c.resolve(new JSObject().put("path",client.printWorkingDirectory()).put("entries",entries(client.listFiles())));}catch(Exception e){c.reject(e.getMessage());}});}
    @PluginMethod public void disconnectPs4(PluginCall c){io.execute(()->{disconnect();c.resolve();});}
    private JSArray entries(FTPFile[] files){JSArray a=new JSArray();for(FTPFile f:files)if(!f.getName().equals(".")&&!f.getName().equals(".."))a.put(new JSObject().put("name",f.getName()).put("directory",f.isDirectory()).put("size",f.getSize()));return a;}
    private void disconnect(){try{if(client!=null&&client.isConnected()){client.logout();client.disconnect();}}catch(Exception ignored){}client=null;}
    private static String validName(String n)throws Exception{if(n==null||n.trim().isEmpty()||n.equals(".")||n.equals("..")||n.contains("/")||n.contains("\\"))throw new IOException("Nombre de archivo o carpeta inválido.");return n.trim();}
    private static void deleteTree(File f)throws IOException{if(f.isDirectory()){File[] children=f.listFiles();if(children!=null)for(File x:children)deleteTree(x);}if(!f.delete())throw new IOException("No se pudo borrar "+f.getName());}
    private String localIp(){try{Enumeration<NetworkInterface> ns=NetworkInterface.getNetworkInterfaces();while(ns.hasMoreElements()){NetworkInterface n=ns.nextElement();if(!n.isUp()||n.isLoopback())continue;Enumeration<InetAddress> as=n.getInetAddresses();while(as.hasMoreElements()){InetAddress a=as.nextElement();if(a instanceof Inet4Address&&a.isSiteLocalAddress()&&!a.isLoopbackAddress())return a.getHostAddress();}}}catch(Exception ignored){}return "";}
    @Override protected void handleOnDestroy(){disconnect();for(FileOutputStream f:uploads.values())try{f.close();}catch(Exception ignored){}uploads.clear();io.shutdownNow();super.handleOnDestroy();}
}
